// 'hesab.js' modul məntiqinin simulyasiyası
export const VALYUTA = "AZN";

export function meblegFormatla(qiymet) {
  return `${qiymet.toFixed(2)} ${VALYUTA}`;
}

export function endirimHesabla(qiymet, faiz) {
  return qiymet - (qiymet * faiz) / 100;
}

// Digər faylda: import { meblegFormatla, endirimHesabla as endirim } from './hesab.js';
const ilkinQiymet = 120;
const endirimli = endirimHesabla(ilkinQiymet, 25);

console.log("Yekun:", meblegFormatla(endirimli));

// 'avtomobil.js' modulu: default klas və named xassələr
export const MASIN_VERGI = 0.18;

export default class Avtomobil {
  constructor(model, qiymet) {
    this.model = model;
    this.qiymet = qiymet;
  }
  yekunQiymet() {
    return this.qiymet + (this.qiymet * MASIN_VERGI);
  }
}

// İstifadə nümunəsi
const masin = new Avtomobil("Tesla Model 3", 50000);
console.log(masin.model);
console.log("Vergili Qiymət:", masin.yekunQiymet());

